78		if len(r.Rejections) != 1 || !sameReasons(r.Rejections[0].Reasons, want) {
79			t.Fatalf("状态变化后历史拒绝原因被改写：保存=%v 读到=%v",
80				want, r.Rejections)
81		}
82	
83		// 正常操作触发台账写盘后，从同一文件读出的历史仍保持原样。
84		reopened, err := openAt(path, clock.now)
85		if err != nil {
86			t.Fatalf("reopen: %v", err)
87		}
88		recs = reopened.UsageRecords()
89		if len(recs) != 1 || recs[0].Allowed || !sameReasons(recs[0].Reasons, want) {
90			t.Fatalf("写盘后历史拒绝被污染：%+v", recs)
91		}
92		rr, _ := reopened.Review("M-1")
93		if len(rr.Rejections) != 1 || !sameReasons(rr.Rejections[0].Reasons, want) {
94			t.Fatalf("写盘后核对视图历史被污染：%+v", rr.Rejections)
95		}
96	}
97	
98	// TestSeparatelyFetchedResultsAreIndependent 验证分别取得的两份结果
99	// 互不影响：整理其中一份的原因，另一份已取得的原因不能跟着改变。
100	func TestSeparatelyFetchedResultsAreIndependent(t *testing.T) {
101		clock := &fakeClock{t: mustDate(t, "2026-10-02")}
102		l := newTestLedger(t, clock)
103		mustRegister(t, l, "M-1", "万用表", 0.5)
104		_, _ = l.RequestUse("M-1")
105	
106		first, _ := l.Review("M-1")
107		want := append([]string(nil), first.Rejections[0].Reasons...)
108		second, _ := l.Review("M-1")
109		listA := l.UsageRecords()
110		listB := l.UsageRecords()
111	
112		// 整理第一份核对结果，第二份核对结果与两份清单都不能跟着改变。
113		first.Rejections[0].Reasons[0] = "第一份核对的改写"
114		if !sameReasons(second.Rejections[0].Reasons, want) {
115			t.Fatal("整理第一份核对结果影响了第二份核对结果")
116		}
117		if !sameReasons(listA[0].Reasons, want) || !sameReasons(listB[0].Reasons, want) {
118			t.Fatal("整理第一份核对结果影响了已取得的使用记录清单")
119		}
120	
121		// 整理第二份核对结果，第一份与台账内历史都不能跟着改变。
122		second.Rejections[0].Reasons = append(second.Rejections[0].Reasons, "第二份追加")
123		if sameReasons(second.Rejections[0].Reasons, want) {
124			t.Fatal("测试前提失效：第二份自身的整理没有生效")
125		}
126		if first.Rejections[0].Reasons[0] != "第一份核对的改写" {
127			t.Fatal("整理第二份核对结果影响了第一份")
128		}
129		if !sameReasons(l.UsageRecords()[0].Reasons, want) {
130			t.Fatal("整理核对结果改写了台账内的历史")
131		}
132	
133		// 分别取得的两份清单互相独立，整理任何一份都不回写台账。
134		listA[0].Reasons[0] = "第一份清单的改写"
135		listB[0].Reasons = listB[0].Reasons[:0]
136		if listA[0].Reasons[0] != "第一份清单的改写" || len(listB[0].Reasons) != 0 {
137			t.Fatal("测试前提失效：清单自身的整理没有生效")
138		}
139		if !sameReasons(l.UsageRecords()[0].Reasons, want) {
140			t.Fatal("整理返回清单改写了台账内的历史")
141		}
142	}
143	
144	// TestAllowedDecisionMutationStaysAllowed 验证允许使用的申请留痕原因为空，
145	// 调用方自行给返回结果添加原因不得把这次申请变成历史拒绝。
146	func TestAllowedDecisionMutationStaysAllowed(t *testing.T) {
147		clock := &fakeClock{t: mustDate(t, "2026-10-02")}
148		path := filepath.Join(t.TempDir(), "ledger.json")
149		l, err := openAt(path, clock.now)
150		if err != nil {
151			t.Fatalf("open: %v", err)
152		}
153		mustRegister(t, l, "M-1", "万用表", 0.5)
154		_ = l.SetStatus("M-1", StatusInUse)
155		mustAddCert(t, l, CertificateInput{
156			InstrumentID: "M-1", Number: "C-1", CalDate: "2026-09-01",
157			Expiry: "2027-09-01", Method: "m", Error: 0, Summary: "s",
158		})
159	
160		d, err := l.RequestUse("M-1")
161		if err != nil || !d.Allowed {
162			t.Fatalf("应允许使用，err=%v allowed=%v", err, d.Allowed)
163		}
164		if len(d.Reasons) != 0 {
165			t.Fatalf("允许使用时原因应为空，得到 %v", d.Reasons)
166		}
167		// 调用方给自己的返回结果添加原因。
168		d.Reasons = append(d.Reasons, "调用方自行添加的展示原因")
169	
170		recs := l.UsageRecords()
171		if len(recs) != 1 || !recs[0].Allowed || len(recs[0].Reasons) != 0 {
172			t.Fatalf("允许记录被变成历史拒绝或原因被污染：%+v", recs[0])
173		}
174		r, _ := l.Review("M-1")
175		if len(r.Rejections) != 0 {
176			t.Fatalf("允许的使用申请不得出现在历史拒绝中：%+v", r.Rejections)
177		}
178	
179		// 写盘重开后仍是允许、原因空。
180		_ = l.SetStatus("M-1", StatusRetired)
181		reopened, _ := openAt(path, clock.now)
182		recs = reopened.UsageRecords()
183		if len(recs) != 1 || !recs[0].Allowed || len(recs[0].Reasons) != 0 {
184			t.Fatalf("写盘后允许记录被污染：%+v", recs[0])
185		}
186	}
187	
188	// TestQueriesDoNotRecordAndEmptyStaysEmpty 验证查询不新增申请，
189	// 没有使用记录时返回空结果，未知器具申请报错且不留痕。
190	func TestQueriesDoNotRecordAndEmptyStaysEmpty(t *testing.T) {
191		clock := &fakeClock{t: mustDate(t, "2026-10-02")}
192		l := newTestLedger(t, clock)
193		mustRegister(t, l, "M-1", "万用表", 0.5)
194	
195		if recs := l.UsageRecords(); len(recs) != 0 {
196			t.Fatalf("没有使用记录时应返回空结果，得到 %+v", recs)
197		}
198		if _, err := l.CanUse("M-1"); err != nil {
199			t.Fatalf("can use: %v", err)
200		}
201		if _, err := l.Review("M-1"); err != nil {
202			t.Fatalf("review: %v", err)
203		}
204		if recs := l.UsageRecords(); len(recs) != 0 {
205			t.Fatalf("查询本身不应新增申请，得到 %d 条", len(recs))
206		}
207		if _, err := l.RequestUse("NOPE"); err == nil {
208			t.Fatal("未知器具的申请应明确报错")
209		}
210		if recs := l.UsageRecords(); len(recs) != 0 {
211			t.Fatal("未知器具的申请不应留痕")
212		}
213	}
